/* R07 approved timber plaza: original XYZ surface, single motif, no slab. */
(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.Red90=api;})(this,()=>{
let config=null,regions=[],holes=[];function prepare(cfg,earcut){config=cfg;const tri=p=>{const ix=earcut(p.flat()),ts=[];for(let i=0;i<ix.length;i+=3){const t=ix.slice(i,i+3).map(j=>p[j]);if((t[1][0]-t[0][0])*(t[2][1]-t[0][1])-(t[1][1]-t[0][1])*(t[2][0]-t[0][0])<0)t.reverse();ts.push(t);}return ts;};holes=cfg.holes.flatMap(tri);regions=[...cfg.treeHoles.map(p=>({p,kind:'redGravel90'})),{p:cfg.polygon,kind:'red90'}].map(r=>({...r,masks:tri(r.p),box:[Math.min(...r.p.map(p=>p[0])),Math.min(...r.p.map(p=>p[1])),Math.max(...r.p.map(p=>p[0])),Math.max(...r.p.map(p=>p[1]))]}));}
function cut(vs,a,b){const d=v=>(b[0]-a[0])*(v[2]-a[1])-(b[1]-a[1])*(v[0]-a[0]),pos=[],neg=[];for(let i=0;i<vs.length;i++){const p=vs[i],q=vs[(i+1)%vs.length],dp=d(p),dq=d(q);if(dp>=0)pos.push(p);if(dp<=0)neg.push(p);if((dp<0&&dq>0)||(dp>0&&dq<0)){const t=dp/(dp-dq),r=p.map((x,j)=>x+(q[j]-x)*t);pos.push(r);neg.push(r);}}return[pos,neg];}
function split(vs,mask){let inner=vs,out=[];for(let k=0;k<3&&inner.length>=3;k++){const[a,b]=cut(inner,mask[k],mask[(k+1)%3]);if(b.length>=3)out.push(b);inner=a;}return{inner,out};}

function overlap(p,b){return !(p.every(v=>v[0]<b[0])||p.every(v=>v[0]>b[2])||p.every(v=>v[2]<b[1])||p.every(v=>v[2]>b[3]));}
function partition(pos,indices,kind){if(!regions.length)return [{pos,indices,kind}];let box=[Infinity,Infinity,-Infinity,-Infinity];for(let i=0;i<pos.length;i+=3){box[0]=Math.min(box[0],pos[i]);box[1]=Math.min(box[1],pos[i+2]);box[2]=Math.max(box[2],pos[i]);box[3]=Math.max(box[3],pos[i+2]);}if(!regions.some(r=>box[0]<=r.box[2]&&box[2]>=r.box[0]&&box[1]<=r.box[3]&&box[3]>=r.box[1]))return [{pos,indices,kind}];const groups=new Map(),put=(k,p)=>{if(!groups.has(k))groups.set(k,{pos:[],indices:[],kind:k});const g=groups.get(k);for(let i=1;i<p.length-1;i++){const a=p[0],b=p[i],c=p[i+1];if(Math.abs((b[0]-a[0])*(c[2]-a[2])-(b[2]-a[2])*(c[0]-a[0]))<1e-10)continue;const j=g.pos.length/3;g.pos.push(...a,...b,...c);g.indices.push(j,j+1,j+2);}};
for(let i=0;i<indices.length;i+=3){const tri=Array.from(indices.slice(i,i+3),j=>Array.from(pos.slice(j*3,j*3+3)));let rest=[tri];for(const r of regions){if(!overlap(tri,r.box)||r.onlyGrass&&!['grass','planting','soil','plaza','path'].includes(kind))continue;for(const mask of r.masks){const next=[];for(const p of rest){const q=split(p,mask);if(q.inner.length>=3){let fill=[q.inner];for(const h of holes){const nn=[];for(const f of fill){const c=split(f,h);if(c.inner.length>=3)put(kind,c.inner);nn.push(...c.out);}fill=nn;}for(const f of fill)put(r.kind,f);}next.push(...q.out);}rest=next;}}for(const p of rest)put(kind,p);}return [...groups.values()].filter(g=>g.indices.length);}


function blocked(x,z,r){if(!config||x<-102||x>-42||z<-377||z>-316)return false;for(const b of config.benches){const dx=x-b.x,dz=z-b.z,co=Math.cos(b.angle),si=Math.sin(b.angle),u=dx*co-dz*si,v=dx*si+dz*co;if(Math.abs(u)<1.7+r&&Math.abs(v)<.35+r)return true;}for(const p of config.planters)if(Math.abs(x-p[0])<.9+r&&Math.abs(z-p[1])<.35+r)return true;return false;}
function build(B,scene,world){if(!config)return;const groups={},mats={};for(const[k,color]of Object.entries({wood:'#a58a65',steel:'#4f5e59',pot:'#a8afa3',leaf:'#7e9565'})){const m=new B.StandardMaterial('red90-'+k,scene);m.diffuseColor=B.Color3.FromHexString(color);m.specularColor=B.Color3.Black();mats[k]=m;groups[k]=[];}const box=(k,x,y,z,w,h,d,angle=0)=>{const m=B.MeshBuilder.CreateBox('red90-part',{width:w,height:h,depth:d},scene);m.position.set(x,y+h/2,z);m.rotation.y=angle;groups[k].push(m);};for(const b of config.benches){const y=world.floorAt(b.x,b.z);for(const u of[-1.18,1.18]){const x=b.x+u*Math.cos(b.angle),z=b.z-u*Math.sin(b.angle);box('steel',x,world.floorAt(x,z),z,.14,y+.46-world.floorAt(x,z),.58,b.angle);}for(const v of[-.24,0,.24])box('wood',b.x+v*Math.sin(b.angle),y+.46,b.z+v*Math.cos(b.angle),3.4,.08,.21,b.angle);}for(const p of config.planters){const y=world.floorAt(...p);box('pot',p[0],y,p[1],1.8,.38,.7);for(const dx of[-.55,0,.55]){const m=B.MeshBuilder.CreateSphere('red90-low-plant',{diameter:.65,segments:4},scene);m.position.set(p[0]+dx,y+.53,p[1]);m.scaling.y=.75;groups.leaf.push(m);}}for(const[k,ms]of Object.entries(groups)){const m=B.Mesh.MergeMeshes(ms,true,true);m.name='red90-'+k;m.material=mats[k];m.isPickable=false;m.freezeWorldMatrix();}return{benches:4,planters:4};}
function gravel(B,scene){const m=new B.StandardMaterial('red90-tree-gravel',scene),t=new B.DynamicTexture('red90-gravel',256,scene,true),c=t.getContext(),im=c.createImageData(256,256);let seed=901;for(let i=0;i<im.data.length;i+=4){seed=(1664525*seed+1013904223)>>>0;const n=(seed/4294967296-.5)*26;im.data[i]=172+n;im.data[i+1]=174+n;im.data[i+2]=158+n;im.data[i+3]=255;}c.putImageData(im,0,0);t.update();t.wrapU=t.wrapV=B.Texture.WRAP_ADDRESSMODE;t.anisotropicFilteringLevel=8;m.diffuseTexture=t;m.specularColor=B.Color3.Black();return m;}
return{prepare,partition,blocked,build,gravel};});
